-- The analog factory module takes glide, mono / legato and two control outputs (#738: params `glide` 0…2 s and `mono` poly | mono |
-- legato, appended after the 91 so no index moves; outputs `env` and `level`), so that the catalog's `module:analog` keeps the
-- repository's files byte for byte (server tests/Unit/Domain/FactoryModulesTest). A new migration, not an edit of
-- 2026-11-21-analog-dsp-units (it runs before this one, by name). Four files take their new text (engine.rs, lib.rs, params.rs,
-- voice.rs); lfo.rs and pan.rs stay. At the new params' defaults (glide 0, poly) the sound is the same bit for bit
-- (deck/modules/analog/tests/golden.rs), so stored presets and shows that do not name them play as before. The descriptor and the
-- wasm in the entry stay as they are until an admin presses Compile on module:analog (POST /api/modules/compile { factory:
-- "analog" }); until then the deck plays the build it has.
-- What it touches: catalog_modules: the row `analog` when it is a factory module already on the SDK's units (no svf.rs) and
-- without the `level` output. entity_versions: the factory's published version of `module:analog` takes the entry's data (no
-- new version: a factory module is the repository's and nobody edits it).
-- Dry run (before): SELECT id, INSTR(JSON_UNQUOTE(JSON_EXTRACT(data, '$.files."params.rs"')), 'name = "level"') > 0 FROM
--   catalog_modules WHERE id = 'analog';  -> expected: one row, 0.
-- Test (after): the same query -> one row, 1; SELECT JSON_LENGTH(data, '$.files') FROM catalog_modules WHERE id = 'analog'; -> 6.
-- Plan's row counts: 1 . 1. MariaDB 10.11, idempotent: the `level` guard stops a second run; the version is only touched while
-- it differs.
-- Escaping: plain string literals (no NO_BACKSLASH_ESCAPES): a doubled backslash is one backslash, \' a quote, \n a newline of
-- the source text.

UPDATE `catalog_modules`
   SET `data` = JSON_SET(`data`,
       '$.files."engine.rs"', '//! The voice pool: eight voices, played by note events (module ABI v2, #343). A note on starts a note on a free voice – or\n//! steals the oldest – keyed by the note\'s **id**, never by its pitch; its note off releases that voice, so a note\'s tail\n//! keeps sounding on its own voice while the next notes start. A note on for an id that still sounds is a legato pitch\n//! change of that voice; a bend (a per-note expression, semitones) moves the voice\'s pitch from the note\'s own; a reset\n//! releases everything. The sustain control holds released notes while it is up. Events take effect at their frame: the\n//! render cuts the block there, so a note lands on its sample however the host cuts the blocks.\n//!\n//! `mono` and `legato` play voice 0 alone from a stack of the held notes (the newest sounds; its note off goes back to the\n//! one under it); mono restarts the envelopes on every note, legato only when no other note is held. `glide` slides every\n//! new note from the last note\'s pitch. Two control outputs, once a block: amp envelope 1 of the newest sounding voice and\n//! the output\'s level.\nuse deck_module::dsp::arith::exp2;\nuse deck_module::dsp::follower::Follower;\nuse crate::params::Patch;\nuse crate::voice::{Note, Voice};\nuse deck_module::{Ev, Expr, Kind, Tempo};\n\npub const VOICES: usize = 8;\n/// the held notes mono and legato remember (more: the oldest is forgotten)\npub const HELD: usize = 16;\n/// the level output\'s follower: up, down (s)\nconst LEVEL_TIMES: (f32, f32) = (0.005, 0.15);\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\nenum Mode {\n    Poly,\n    Mono,\n    Legato,\n}\n\nimpl Mode {\n    fn of(p: &Patch) -> Mode {\n        match p.mono.round() as i32 {\n            1 => Mode::Mono,\n            2 => Mode::Legato,\n            _ => Mode::Poly,\n        }\n    }\n}\n\n#[derive(Default)]\npub struct Engine {\n    voices: [Voice; VOICES],\n    sustain: bool,\n    next_age: u64,\n    seed: u64,\n    rate: f64,\n    /// mono / legato: the held notes (id, Hz, velocity), the newest last\n    held: [(u32, f32, f32); HELD],\n    held_n: usize,\n    /// the pitch of the last note on (where a glide starts; 0 = none yet)\n    last_hz: f32,\n    follower: Follower,\n    outputs: (f32, f32),\n}\n\nimpl Engine {\n    pub fn init(&mut self, rate: f64, seed: u64) {\n        let rate = rate.max(1.0);\n        let follower = Follower::new(LEVEL_TIMES.0, LEVEL_TIMES.1, rate as f32);\n        *self = Engine { rate, seed, follower, ..Engine::default() };\n    }\n\n    /// the control outputs after the last render: (amp envelope 1 of the newest sounding voice, the output\'s level)\n    pub fn outputs(&self) -> (f32, f32) {\n        self.outputs\n    }\n\n    pub fn active_voices(&self) -> usize {\n        self.voices.iter().filter(|v| v.active()).count()\n    }\n\n    /// the voice the note `id` holds\n    fn held(&self, id: u32) -> Option<usize> {\n        self.voices.iter().position(|v| v.active() && v.id() == Some(id))\n    }\n\n    fn new_note(&mut self, id: u32, hz: f32, vel: f32, p: &Patch) -> Note {\n        let age = self.next_age;\n        self.next_age += 1;\n        let from = if p.glide > 0.0 { self.last_hz } else { 0.0 };\n        self.last_hz = hz;\n        Note { hz, vel, id, age, seed: self.seed ^ age.wrapping_mul(0x9E37_79B9_7F4A_7C15), from }\n    }\n\n    fn note_on(&mut self, id: u32, hz: f32, vel: f32, p: &Patch) {\n        let mode = Mode::of(p);\n        if mode != Mode::Poly {\n            return self.mono_on(id, hz, vel, mode, p);\n        }\n        self.held_n = 0;\n        if let Some(i) = self.held(id) {\n            self.voices[i].set_pitch(hz);\n            return;\n        }\n        let note = self.new_note(id, hz, vel, p);\n        match self.voices.iter().position(|v| !v.active()) {\n            Some(i) => self.voices[i].start(note, p, self.rate),\n            None => {\n                let oldest = (0..VOICES).min_by_key(|&i| self.voices[i].age()).unwrap_or(0);\n                self.voices[oldest].steal(note);\n            }\n        }\n    }\n\n    /// mono / legato: voice 0 takes the note\n    fn mono_on(&mut self, id: u32, hz: f32, vel: f32, mode: Mode, p: &Patch) {\n        if let Some(k) = self.held[..self.held_n].iter().position(|h| h.0 == id) {\n            self.held[k].1 = hz;\n            if self.voices[0].id() == Some(id) {\n                self.voices[0].legato(id, hz, p, self.rate);\n            }\n            return;\n        }\n        let overlap = self.held_n > 0 && self.voices[0].active() && self.voices[0].id().is_some();\n        if self.held_n == HELD {\n            self.held.copy_within(1.., 0);\n            self.held_n -= 1;\n        }\n        self.held[self.held_n] = (id, hz, vel);\n        self.held_n += 1;\n        if mode == Mode::Legato && overlap {\n            self.last_hz = hz;\n            self.voices[0].legato(id, hz, p, self.rate);\n        } else {\n            let note = self.new_note(id, hz, vel, p);\n            self.voices[0].retrigger(note, p, self.rate);\n        }\n    }\n\n    /// mono / legato: a held note lets go; the sounding one hands voice 0 to the newest note still held\n    fn mono_off(&mut self, id: u32, mode: Mode, p: &Patch) -> bool {\n        let Some(k) = self.held[..self.held_n].iter().position(|h| h.0 == id) else {\n            return false;\n        };\n        self.held.copy_within(k + 1..self.held_n, k);\n        self.held_n -= 1;\n        if self.voices[0].id() != Some(id) {\n            return true;\n        }\n        match self.held_n.checked_sub(1).map(|top| self.held[top]) {\n            Some((next, hz, _)) if mode == Mode::Legato => {\n                self.last_hz = hz;\n                self.voices[0].legato(next, hz, p, self.rate);\n            }\n            Some((next, hz, vel)) => {\n                let note = self.new_note(next, hz, vel, p);\n                self.voices[0].retrigger(note, p, self.rate);\n            }\n            None if self.sustain => self.voices[0].hold(),\n            None => self.voices[0].release(p, self.rate),\n        }\n        true\n    }\n\n    fn note_off(&mut self, id: u32, p: &Patch) {\n        let mode = Mode::of(p);\n        if mode != Mode::Poly && self.mono_off(id, mode, p) {\n            return;\n        }\n        if let Some(i) = self.held(id) {\n            if self.sustain {\n                self.voices[i].hold();\n            } else {\n                self.voices[i].release(p, self.rate);\n            }\n        }\n    }\n\n    fn event(&mut self, e: &Ev, p: &Patch) {\n        match e.kind() {\n            Some(Kind::NoteOn) => {\n                // the host fills Hz from a key and a missing velocity with 1; a note without a pitch is no note\n                let (hz, vel) = (e.pitch_hz(), e.velocity());\n                if hz.is_finite() && hz > 0.0 {\n                    self.note_on(e.id, hz, if vel.is_finite() { vel.min(1.0) } else { 1.0 }, p);\n                }\n            }\n            Some(Kind::NoteOff) => self.note_off(e.id, p),\n            Some(Kind::NoteExpr) => {\n                if let (Some((Expr::Bend, semis)), Some(i)) = (e.expr(), self.held(e.id)) {\n                    if semis.is_finite() {\n                        let base = self.voices[i].base();\n                        self.voices[i].set_pitch((f64::from(base) * exp2(f64::from(semis) / 12.0)) as f32);\n                    }\n                }\n            }\n            Some(Kind::Reset) => {\n                self.held_n = 0;\n                for i in 0..VOICES {\n                    if self.voices[i].active() {\n                        self.voices[i].release(p, self.rate);\n                    }\n                }\n            }\n            _ => {}\n        }\n    }\n\n    /// Render `out.0.len()` frames starting at audio frame `frame0` of the tempo map. `notes` are this call\'s note\n    /// events (sorted by frame), `sustain` the pedal for this call.\n    pub fn render(&mut self, p: &Patch, notes: &[Ev], sustain: bool, tempo: &Tempo, frame0: f64, out: (&mut [f32], &mut [f32])) {\n        let (left, right) = out;\n        if self.sustain && !sustain {\n            for i in 0..VOICES {\n                if self.voices[i].active() && self.voices[i].sustained() {\n                    self.voices[i].release(p, self.rate);\n                }\n            }\n        }\n        self.sustain = sustain;\n        let mut next = 0;\n        for i in 0..left.len().min(right.len()) {\n            while let Some(e) = notes.get(next).filter(|e| e.frame as usize <= i) {\n                self.event(e, p);\n                next += 1;\n            }\n            let beat = tempo.beat_at(frame0 + i as f64);\n            let (mut l, mut r) = (0.0f32, 0.0f32);\n            for v in self.voices.iter_mut().filter(|v| v.active()) {\n                let (a, b) = v.render(p, self.rate, beat);\n                l += a;\n                r += b;\n            }\n            left[i] = l * p.volume;\n            right[i] = r * p.volume;\n            self.follower.tick(left[i].abs().max(right[i].abs()));\n        }\n        // an event past the call\'s frames (a host never sends one) still counts, at its end\n        for e in &notes[next.min(notes.len())..] {\n            self.event(e, p);\n        }\n        let newest = self.voices.iter().filter(|v| v.active()).max_by_key(|v| v.age());\n        self.outputs = (newest.map_or(0.0, |v| v.env()), self.follower.level().min(1.0));\n    }\n}\n',
       '$.files."lib.rs"', '//! `analog` – a classic two-oscillator, two-filter, two-amp subtractive synth as one universal module (#331, README.md):\n//! Osc 1 / Osc 2 (saw, pulse, triangle, sine; a sub each; Osc 2 hard-syncs to Osc 1) and noise → routing → Filter 1 /\n//! Filter 2 (LP, BP, HP, notch; parallel or serial) → Amp 1 / Amp 2 (level, pan) → stereo out, modulated by two LFOs and\n//! four ADSRs, eight voices (or one: mono / legato, with glide). Notes come in on one event input (module ABI v2, #343: note on / off paired by id, with\n//! velocity; a bend per note; a reset) and a sustain control; two control outputs give amp envelope 1 and the output\'s\n//! level; every control is a module parameter (`params.rs`, units and\n//! docs in the descriptor); the factory preset `pad` is the descriptor\'s, the other presets are documents\n//! (`analog.preset.json` holds three to import).\n//!\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p analog-module` (the .wasm in\n//! `target/wasm32-unknown-unknown/release/analog_module.wasm`).\n// one `#[port(…)]` a port: clippy takes them for duplicates (deck/module/README.md)\n#![allow(clippy::duplicated_attributes)]\n// The oscillators, the filter, the envelope and the noise are the SDK\'s units (`deck_module::dsp`); the LFO and the pan\n// law are the synth\'s own. Nothing allocates, reads a clock or calls the platform\'s maths, so a render is bit-identical\n// native ≡ wasm. Flat files beside lib.rs: the build service takes a module as flat `src/*.rs` files only, so the\n// catalog\'s `module:analog` stores exactly these.\npub mod lfo;\npub mod pan;\nmod engine;\nmod params;\nmod voice;\n\npub use engine::VOICES;\npub use params::{Analog, Patch, PARAM_NAMES};\n\nuse deck_module::{Block, Ctx, Module};\n\nimpl Analog {\n    /// how many voices sound (a tail counts)\n    pub fn active_voices(&self) -> usize {\n        self.engine.active_voices()\n    }\n}\n\nimpl Module for Analog {\n    fn init(&mut self, ctx: &Ctx) {\n        self.engine.init(ctx.rate(), ctx.seed());\n    }\n\n    fn process(&mut self, block: &mut Block, ctx: &Ctx) {\n        let patch = self.patch();\n        let sustain = block.control_in(Self::SUSTAIN) >= 0.5;\n        let notes = block.events_in(Self::NOTES);\n        let mut out = block.audio_out(Self::OUT);\n        let (left, right) = out.stereo();\n        self.engine.render(&patch, notes, sustain, &ctx.tempo(), ctx.frame(), (left, right));\n        let (env, level) = self.engine.outputs();\n        block.set(Self::ENV, env);\n        block.set(Self::LEVEL, level);\n    }\n}\n',
       '$.files."params.rs"', '//! The synth\'s parameters: ONE table – each row a `#[param]` attribute (range or choices, default, curve, unit, doc) the\n//! derive reads into the descriptor (#343: the catalog descriptor carries units, choices and docs; no extra section) –\n//! expanded into the module struct, the `Patch` snapshot the voices read and the name list. The factory preset `pad`\n//! is the descriptor\'s one preset (`#[preset]`); every other preset is a document (research/ABI-V2.md §2).\n//!\n//! A switch or a mode is a number: 0 / 1, or 0..n with its `choices` in order (the value is the index). Names are at\n//! most 24 lowercase characters.\n//!\n//! Pages after the Analog Four: an area per button (SRC, FLTR, AMP, LFO, VOICE), pressed again for its next page, eight\n//! knobs a page in two rows of four. Twin pages put one idea on one knob (OSC 1 / OSC 2, FILTER 1 / FILTER 2, LFO 1 /\n//! LFO 2); on the two-channel pages the top row is channel 1 and the bottom row channel 2; a modulation sits on its\n//! source\'s page.\nuse crate::engine::Engine;\nuse deck_module::Module;\n\nmacro_rules! analog {\n    ( $( #[param($($meta:tt)*)] $name:ident; )* ) => {\n        /// the synth: parameters (the table below), the voices behind them\n        #[derive(Module)]\n        #[module(name = "analog", doc = "a classic two-oscillator, two-filter, two-amp subtractive synth, eight voices",\n            sections = ["SRC/OSC 1", "SRC/OSC 2", "SRC/NOISE·ROUTE",\n                        "FLTR/FILTER 1", "FLTR/FILTER 2", "FLTR/FILTER ENV",\n                        "AMP/AMP", "AMP/AMP ENV",\n                        "LFO/LFO 1", "LFO/LFO 1 DEST", "LFO/LFO 2", "LFO/LFO 2 DEST",\n                        "VOICE/VOICE"])]\n        #[port(input, event, name = "notes", names = "music.note", props = "pitch|vel|glide|key", capacity = 64, doc = "notes on and off (by id), a bend per note, a reset")]\n        #[port(input, control, name = "sustain", doc = "the pedal: at 0.5 and above released notes hold")]\n        #[port(output, audio, name = "out", channels = 2, doc = "stereo: the sum of the voices times volume")]\n        #[port(output, control, name = "env", doc = "amp envelope 1 of the newest sounding voice, 0…1, at the end of each block")]\n        #[port(output, control, name = "level", doc = "the output\'s level (a follower: 5 ms up, 150 ms down), 0…1, at the end of each block")]\n        #[preset(name = "pad", doc = "A wide, slow pad: a detuned saw through filter 1 on the left and a pulse with a slow pulse-width sweep through filter 2 on the right, a long filter bloom and a slow filter wobble.", values(volume = 0.6, o1_wave = 0.0, o1_fine = -7.0, o1_level = 0.7, o1_route = 0.0, o2_wave = 1.0, o2_fine = 7.0, o2_pw = 0.5, o2_level = 0.6, o2_route = 1.0, f1_cutoff = 1400.0, f1_res = 0.2, f1_key = 0.5, f1_env = 0.35, f2_cutoff = 2200.0, f2_res = 0.1, f2_key = 0.5, f2_env = 0.2, fe1_a = 1.2, fe1_d = 1.5, fe1_s = 0.5, fe1_r = 1.5, fe2_a = 1.5, fe2_d = 2.0, fe2_s = 0.6, fe2_r = 1.5, a1_level = 0.8, a1_pan = -0.55, a1_vel = 0.3, a2_level = 0.8, a2_pan = 0.55, a2_vel = 0.3, ae1_a = 0.9, ae1_d = 0.8, ae1_s = 0.85, ae1_r = 2.0, ae2_a = 1.1, ae2_d = 0.8, ae2_s = 0.85, ae2_r = 2.2, l1_shape = 0.0, l1_rate = 0.25, l1_f1 = 0.5, l2_shape = 1.0, l2_rate = 0.17, l2_pwm = 0.3, l2_f2 = 0.4))]\n        pub struct Analog {\n            $( #[param($($meta)*)] pub $name: f32, )*\n            pub(crate) engine: Engine,\n        }\n\n        /// every parameter\'s value at one moment: what the voices read\n        #[derive(Debug, Clone, Copy)]\n        pub struct Patch {\n            $( pub $name: f32, )*\n        }\n\n        impl Analog {\n            pub fn patch(&self) -> Patch {\n                Patch { $( $name: self.$name, )* }\n            }\n        }\n\n        /// the parameter names in descriptor order\n        pub const PARAM_NAMES: &[&str] = &[$( stringify!($name), )*];\n    };\n}\n\nanalog! {\n    #[param(range = 0.0..1.0, default = 0.7, doc = "master level: the sum of the voices times this", section = "VOICE/VOICE", slot = 0)] volume;\n\n    #[param(choices = "saw|pulse|triangle|sine", default = 0, doc = "oscillator 1 waveform", section = "SRC/OSC 1", slot = 0)] o1_wave;\n    #[param(range = -24.0..24.0, default = 0.0, unit = "st", doc = "oscillator 1 pitch offset in semitones", section = "SRC/OSC 1", slot = 1)] o1_semi;\n    #[param(range = -100.0..100.0, default = 0.0, unit = "cent", doc = "oscillator 1 fine detune", section = "SRC/OSC 1", slot = 2)] o1_fine;\n    #[param(range = 0.05..0.95, default = 0.5, doc = "oscillator 1 pulse width (the pulse wave only)", section = "SRC/OSC 1", slot = 3)] o1_pw;\n    #[param(range = 0.0..1.0, default = 0.8, doc = "oscillator 1 level", section = "SRC/OSC 1", slot = 4)] o1_level;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "oscillator 1 sub-oscillator level (a square, one octave down)", section = "SRC/OSC 1", slot = 5)] o1_sub;\n    #[param(range = 0.0..1.0, default = 1.0, doc = "oscillator 1 keyboard follow: 1 plays the pitch it is sent, 0 holds middle C", section = "SRC/OSC 1", slot = 6)] o1_key;\n\n    #[param(choices = "saw|pulse|triangle|sine", default = 0, doc = "oscillator 2 waveform", section = "SRC/OSC 2", slot = 0)] o2_wave;\n    #[param(range = -24.0..24.0, default = 0.0, unit = "st", doc = "oscillator 2 pitch offset in semitones", section = "SRC/OSC 2", slot = 1)] o2_semi;\n    #[param(range = -100.0..100.0, default = 0.0, unit = "cent", doc = "oscillator 2 fine detune", section = "SRC/OSC 2", slot = 2)] o2_fine;\n    #[param(range = 0.05..0.95, default = 0.5, doc = "oscillator 2 pulse width (the pulse wave only)", section = "SRC/OSC 2", slot = 3)] o2_pw;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "oscillator 2 level", section = "SRC/OSC 2", slot = 4)] o2_level;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "oscillator 2 sub-oscillator level (a square, one octave down)", section = "SRC/OSC 2", slot = 5)] o2_sub;\n    #[param(range = 0.0..1.0, default = 1.0, doc = "oscillator 2 keyboard follow: 1 plays the pitch it is sent, 0 holds middle C", section = "SRC/OSC 2", slot = 6)] o2_key;\n    #[param(choices = "off|on", default = 0, doc = "hard sync: oscillator 1 restarts oscillator 2 at every cycle", section = "SRC/OSC 2", slot = 7)] o2_sync;\n\n    #[param(range = 0.0..1.0, default = 0.0, doc = "white noise level (seeded, the same on every deck)", section = "SRC/NOISE·ROUTE", slot = 0)] noise_level;\n\n    #[param(choices = "filter 1|filter 2|both", default = 0, doc = "where oscillator 1 goes", section = "SRC/NOISE·ROUTE", slot = 4)] o1_route;\n    #[param(choices = "filter 1|filter 2|both", default = 0, doc = "where oscillator 1\'s sub goes", section = "SRC/NOISE·ROUTE", slot = 5)] sub1_route;\n    #[param(choices = "filter 1|filter 2|both", default = 0, doc = "where oscillator 2 goes", section = "SRC/NOISE·ROUTE", slot = 6)] o2_route;\n    #[param(choices = "filter 1|filter 2|both", default = 0, doc = "where oscillator 2\'s sub goes", section = "SRC/NOISE·ROUTE", slot = 7)] sub2_route;\n    #[param(choices = "filter 1|filter 2|both", default = 0, doc = "where the noise goes", section = "SRC/NOISE·ROUTE", slot = 1)] noise_route;\n    #[param(choices = "parallel|serial", default = 0, doc = "serial: filter 1\'s output also feeds filter 2", section = "SRC/NOISE·ROUTE", slot = 2)] f_serial;\n    #[param(range = 0.0..1.0, default = 1.0, doc = "how much of filter 1 feeds filter 2 (serial only)", section = "SRC/NOISE·ROUTE", slot = 3)] f1_to_f2;\n\n    #[param(range = -12.0..12.0, default = 0.0, unit = "st", doc = "velocity to pitch: semitones at full velocity", section = "VOICE/VOICE", slot = 1)] vel_pitch;\n    #[param(range = -0.45..0.45, default = 0.0, doc = "velocity to pulse width of both oscillators at full velocity", section = "VOICE/VOICE", slot = 2)] vel_pwm;\n\n    #[param(choices = "lowpass|bandpass|highpass|notch", default = 0, doc = "filter 1 type", section = "FLTR/FILTER 1", slot = 4)] f1_mode;\n    #[param(range = 20.0..20000.0, default = 8000.0, curve = log, unit = "Hz", doc = "filter 1 cutoff", section = "FLTR/FILTER 1", slot = 0)] f1_cutoff;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "filter 1 resonance", section = "FLTR/FILTER 1", slot = 1)] f1_res;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "filter 1 drive: saturation in front of the filter", section = "FLTR/FILTER 1", slot = 2)] f1_drive;\n    #[param(range = -1.0..1.0, default = 0.0, doc = "filter 1 key tracking: 1 moves the cutoff an octave per octave of pitch", section = "FLTR/FILTER 1", slot = 5)] f1_key;\n    #[param(range = -1.0..1.0, default = 0.0, doc = "filter 1 envelope amount: six octaves at full", section = "FLTR/FILTER 1", slot = 3)] f1_env;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "velocity to filter 1 cutoff: four octaves at full velocity", section = "FLTR/FILTER 1", slot = 6)] f1_vel;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "velocity to filter 1 resonance", section = "FLTR/FILTER 1", slot = 7)] f1_velres;\n\n    #[param(choices = "lowpass|bandpass|highpass|notch", default = 0, doc = "filter 2 type", section = "FLTR/FILTER 2", slot = 4)] f2_mode;\n    #[param(range = 20.0..20000.0, default = 8000.0, curve = log, unit = "Hz", doc = "filter 2 cutoff", section = "FLTR/FILTER 2", slot = 0)] f2_cutoff;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "filter 2 resonance", section = "FLTR/FILTER 2", slot = 1)] f2_res;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "filter 2 drive: saturation in front of the filter", section = "FLTR/FILTER 2", slot = 2)] f2_drive;\n    #[param(range = -1.0..1.0, default = 0.0, doc = "filter 2 key tracking: 1 moves the cutoff an octave per octave of pitch", section = "FLTR/FILTER 2", slot = 5)] f2_key;\n    #[param(range = -1.0..1.0, default = 0.0, doc = "filter 2 envelope amount: six octaves at full", section = "FLTR/FILTER 2", slot = 3)] f2_env;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "velocity to filter 2 cutoff: four octaves at full velocity", section = "FLTR/FILTER 2", slot = 6)] f2_vel;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "velocity to filter 2 resonance", section = "FLTR/FILTER 2", slot = 7)] f2_velres;\n\n    #[param(range = 0.001..10.0, default = 0.005, curve = log, unit = "s", doc = "filter envelope 1 attack", section = "FLTR/FILTER ENV", slot = 0)] fe1_a;\n    #[param(range = 0.001..10.0, default = 0.3, curve = log, unit = "s", doc = "filter envelope 1 decay", section = "FLTR/FILTER ENV", slot = 1)] fe1_d;\n    #[param(range = 0.0..1.0, default = 0.5, doc = "filter envelope 1 sustain level", section = "FLTR/FILTER ENV", slot = 2)] fe1_s;\n    #[param(range = 0.001..10.0, default = 0.3, curve = log, unit = "s", doc = "filter envelope 1 release", section = "FLTR/FILTER ENV", slot = 3)] fe1_r;\n    #[param(range = 0.001..10.0, default = 0.005, curve = log, unit = "s", doc = "filter envelope 2 attack", section = "FLTR/FILTER ENV", slot = 4)] fe2_a;\n    #[param(range = 0.001..10.0, default = 0.3, curve = log, unit = "s", doc = "filter envelope 2 decay", section = "FLTR/FILTER ENV", slot = 5)] fe2_d;\n    #[param(range = 0.0..1.0, default = 0.5, doc = "filter envelope 2 sustain level", section = "FLTR/FILTER ENV", slot = 6)] fe2_s;\n    #[param(range = 0.001..10.0, default = 0.3, curve = log, unit = "s", doc = "filter envelope 2 release", section = "FLTR/FILTER ENV", slot = 7)] fe2_r;\n    #[param(range = -24.0..24.0, default = 0.0, unit = "st", doc = "filter envelope 2 to oscillator 2 pitch only: semitones at full (the classic sync sweep)", section = "VOICE/VOICE", slot = 3)] fe2_p2;\n\n    #[param(range = 0.0..1.0, default = 0.8, doc = "amp 1 level (filter 1\'s output)", section = "AMP/AMP", slot = 0)] a1_level;\n    #[param(range = -1.0..1.0, default = 0.0, doc = "amp 1 pan, constant power", section = "AMP/AMP", slot = 1)] a1_pan;\n    #[param(range = 0.0..1.0, default = 0.5, doc = "velocity to amp 1 level", section = "AMP/AMP", slot = 2)] a1_vel;\n    #[param(range = -1.0..1.0, default = 0.0, doc = "amp 1 key tracking: level change with pitch, 3 dB an octave at full", section = "AMP/AMP", slot = 3)] a1_key;\n    #[param(range = 0.0..1.0, default = 0.8, doc = "amp 2 level (filter 2\'s output)", section = "AMP/AMP", slot = 4)] a2_level;\n    #[param(range = -1.0..1.0, default = 0.0, doc = "amp 2 pan, constant power", section = "AMP/AMP", slot = 5)] a2_pan;\n    #[param(range = 0.0..1.0, default = 0.5, doc = "velocity to amp 2 level", section = "AMP/AMP", slot = 6)] a2_vel;\n    #[param(range = -1.0..1.0, default = 0.0, doc = "amp 2 key tracking: level change with pitch, 3 dB an octave at full", section = "AMP/AMP", slot = 7)] a2_key;\n\n    #[param(range = 0.001..10.0, default = 0.003, curve = log, unit = "s", doc = "amp envelope 1 attack", section = "AMP/AMP ENV", slot = 0)] ae1_a;\n    #[param(range = 0.001..10.0, default = 0.3, curve = log, unit = "s", doc = "amp envelope 1 decay", section = "AMP/AMP ENV", slot = 1)] ae1_d;\n    #[param(range = 0.0..1.0, default = 0.8, doc = "amp envelope 1 sustain level", section = "AMP/AMP ENV", slot = 2)] ae1_s;\n    #[param(range = 0.001..10.0, default = 0.25, curve = log, unit = "s", doc = "amp envelope 1 release", section = "AMP/AMP ENV", slot = 3)] ae1_r;\n    #[param(range = 0.001..10.0, default = 0.003, curve = log, unit = "s", doc = "amp envelope 2 attack", section = "AMP/AMP ENV", slot = 4)] ae2_a;\n    #[param(range = 0.001..10.0, default = 0.3, curve = log, unit = "s", doc = "amp envelope 2 decay", section = "AMP/AMP ENV", slot = 5)] ae2_d;\n    #[param(range = 0.0..1.0, default = 0.8, doc = "amp envelope 2 sustain level", section = "AMP/AMP ENV", slot = 6)] ae2_s;\n    #[param(range = 0.001..10.0, default = 0.25, curve = log, unit = "s", doc = "amp envelope 2 release", section = "AMP/AMP ENV", slot = 7)] ae2_r;\n\n    #[param(choices = "sine|triangle|saw|square|sample & hold", default = 0, doc = "LFO 1 shape", section = "LFO/LFO 1", slot = 4)] l1_shape;\n    #[param(range = 0.01..40.0, default = 4.0, curve = log, unit = "Hz", doc = "LFO 1 rate when free-running", section = "LFO/LFO 1", slot = 0)] l1_rate;\n    #[param(choices = "free|2 bars|1 bar|1/2|1/4|1/8|1/16|1/32", default = 0, doc = "LFO 1 tempo sync: a cycle per note value, locked to the beat", section = "LFO/LFO 1", slot = 1)] l1_sync;\n    #[param(range = 0.0..5.0, default = 0.0, unit = "s", doc = "LFO 1 delay: silent for this long after the note starts", section = "LFO/LFO 1", slot = 2)] l1_delay;\n    #[param(range = 0.0..5.0, default = 0.0, unit = "s", doc = "LFO 1 attack: fades in over this long after the delay", section = "LFO/LFO 1", slot = 3)] l1_attack;\n    #[param(range = 0.0..12.0, default = 0.0, unit = "st", doc = "LFO 1 to pitch of both oscillators: semitones either way (vibrato)", section = "LFO/LFO 1 DEST", slot = 0)] l1_pitch;\n    #[param(range = 0.0..0.45, default = 0.0, doc = "LFO 1 to the pulse width of both oscillators", section = "LFO/LFO 1 DEST", slot = 2)] l1_pwm;\n    #[param(range = 0.0..4.0, default = 0.0, unit = "oct", doc = "LFO 1 to filter 1 cutoff: octaves either way", section = "LFO/LFO 1 DEST", slot = 4)] l1_f1;\n    #[param(range = 0.0..4.0, default = 0.0, unit = "oct", doc = "LFO 1 to filter 2 cutoff: octaves either way", section = "LFO/LFO 1 DEST", slot = 5)] l1_f2;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "LFO 1 to amp 1 level (tremolo depth)", section = "LFO/LFO 1 DEST", slot = 6)] l1_a1;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "LFO 1 to amp 2 level (tremolo depth)", section = "LFO/LFO 1 DEST", slot = 7)] l1_a2;\n    #[param(range = 0.0..12.0, default = 0.0, unit = "st", doc = "LFO 1 to oscillator 2 pitch only: semitones either way (sweeps a synced oscillator)", section = "LFO/LFO 1 DEST", slot = 1)] l1_p2;\n\n    #[param(choices = "sine|triangle|saw|square|sample & hold", default = 0, doc = "LFO 2 shape", section = "LFO/LFO 2", slot = 4)] l2_shape;\n    #[param(range = 0.01..40.0, default = 4.0, curve = log, unit = "Hz", doc = "LFO 2 rate when free-running", section = "LFO/LFO 2", slot = 0)] l2_rate;\n    #[param(choices = "free|2 bars|1 bar|1/2|1/4|1/8|1/16|1/32", default = 0, doc = "LFO 2 tempo sync: a cycle per note value, locked to the beat", section = "LFO/LFO 2", slot = 1)] l2_sync;\n    #[param(range = 0.0..5.0, default = 0.0, unit = "s", doc = "LFO 2 delay: silent for this long after the note starts", section = "LFO/LFO 2", slot = 2)] l2_delay;\n    #[param(range = 0.0..5.0, default = 0.0, unit = "s", doc = "LFO 2 attack: fades in over this long after the delay", section = "LFO/LFO 2", slot = 3)] l2_attack;\n    #[param(range = 0.0..12.0, default = 0.0, unit = "st", doc = "LFO 2 to pitch of both oscillators: semitones either way (vibrato)", section = "LFO/LFO 2 DEST", slot = 0)] l2_pitch;\n    #[param(range = 0.0..0.45, default = 0.0, doc = "LFO 2 to the pulse width of both oscillators", section = "LFO/LFO 2 DEST", slot = 2)] l2_pwm;\n    #[param(range = 0.0..4.0, default = 0.0, unit = "oct", doc = "LFO 2 to filter 1 cutoff: octaves either way", section = "LFO/LFO 2 DEST", slot = 4)] l2_f1;\n    #[param(range = 0.0..4.0, default = 0.0, unit = "oct", doc = "LFO 2 to filter 2 cutoff: octaves either way", section = "LFO/LFO 2 DEST", slot = 5)] l2_f2;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "LFO 2 to amp 1 level (tremolo depth)", section = "LFO/LFO 2 DEST", slot = 6)] l2_a1;\n    #[param(range = 0.0..1.0, default = 0.0, doc = "LFO 2 to amp 2 level (tremolo depth)", section = "LFO/LFO 2 DEST", slot = 7)] l2_a2;\n    #[param(range = 0.0..12.0, default = 0.0, unit = "st", doc = "LFO 2 to oscillator 2 pitch only: semitones either way (sweeps a synced oscillator)", section = "LFO/LFO 2 DEST", slot = 1)] l2_p2;\n\n    #[param(range = 0.0..2.0, default = 0.0, unit = "s", doc = "glide: the time a note takes to slide from the last note\'s pitch to its own, in even semitone steps (0 = off)", section = "VOICE/VOICE", slot = 4)] glide;\n    #[param(choices = "poly|mono|legato", default = 0, doc = "poly: eight voices; mono: one voice, every note restarts the envelopes; legato: one voice, a note played while another is held only moves the pitch", section = "VOICE/VOICE", slot = 5)] mono;\n}\n',
       '$.files."voice.rs"', '//! One voice: the whole chain of the schema – Osc 1 / Osc 2 (+ their subs) / noise → routing → Filter 1 / Filter 2 →\n//! Amp 1 / Amp 2 → stereo – with its two LFOs and four envelopes. Modulation is read every sample; what is costly (the\n//! pitch, the cutoffs, the pan) is recomputed every `CTRL` samples of the voice\'s own clock, so a render does not\n//! depend on how the host cut the audio into blocks.\nuse crate::lfo::{self, Lfo, Settings as LfoSettings, Shape};\nuse crate::pan;\nuse crate::params::Patch;\nuse deck_module::dsp::adsr::{Adsr, Times};\nuse deck_module::dsp::arith::{exp2, log2, C4};\nuse deck_module::dsp::noise::{mix, White};\nuse deck_module::dsp::osc::{Osc, Sub, Wave};\nuse deck_module::dsp::svf::{self, Coef, Mode, Svf};\n\n/// samples between the control-rate updates (0.33 ms at 48 kHz)\npub const CTRL: u32 = 16;\n/// samples a stolen voice takes to fade out before the new note starts (1 ms)\npub const FADE: u32 = 48;\n\n/// a note on its way into a voice\n#[derive(Debug, Clone, Copy)]\npub struct Note {\n    pub hz: f32,\n    pub vel: f32,\n    /// the note event\'s id: its note off and bends find the voice by it\n    pub id: u32,\n    /// the note counter: smaller = older\n    pub age: u64,\n    pub seed: u64,\n    /// the pitch a glide starts from (Hz; 0 = none)\n    pub from: f32,\n}\n\nfn fe_times(p: &Patch, n: usize) -> Times {\n    if n == 0 {\n        Times { attack: p.fe1_a, decay: p.fe1_d, sustain: p.fe1_s, release: p.fe1_r }\n    } else {\n        Times { attack: p.fe2_a, decay: p.fe2_d, sustain: p.fe2_s, release: p.fe2_r }\n    }\n}\n\nfn ae_times(p: &Patch, n: usize) -> Times {\n    if n == 0 {\n        Times { attack: p.ae1_a, decay: p.ae1_d, sustain: p.ae1_s, release: p.ae1_r }\n    } else {\n        Times { attack: p.ae2_a, decay: p.ae2_d, sustain: p.ae2_s, release: p.ae2_r }\n    }\n}\n\nfn lfo_settings(p: &Patch, n: usize) -> LfoSettings {\n    let (shape, rate_hz, sync, delay, attack) = if n == 0 {\n        (p.l1_shape, p.l1_rate, p.l1_sync, p.l1_delay, p.l1_attack)\n    } else {\n        (p.l2_shape, p.l2_rate, p.l2_sync, p.l2_delay, p.l2_attack)\n    };\n    LfoSettings { shape: Shape::from_param(shape), rate_hz, beats: lfo::beats_per_cycle(sync), delay, attack }\n}\n\n#[derive(Default)]\npub struct Voice {\n    active: bool,\n    /// the note counter of the note it plays (steal the smallest)\n    age: u64,\n    /// the note that holds it (its id; none once released)\n    id: Option<u32>,\n    /// the note\'s own pitch (a bend moves from here)\n    base: f32,\n    /// the gate is gone but the sustain pedal holds it\n    sustained: bool,\n    hz: f32,\n    vel: f32,\n    ctr: u32,\n    /// a glide: the pitch it ends on, the control steps left, where it is and its step (octaves)\n    target: f32,\n    glide_left: u32,\n    glide_oct: f64,\n    glide_step: f64,\n    osc: [Osc; 2],\n    sub: [Sub; 2],\n    noise: White,\n    svf: [Svf; 2],\n    coef: [Coef; 2],\n    fenv: [Adsr; 2],\n    aenv: [Adsr; 2],\n    lfo: [Lfo; 2],\n    lfo_v: [f32; 2],\n    fe_v: [f32; 2],\n    inc: [f64; 2],\n    pw: [f64; 2],\n    amp: [f32; 2],\n    pan: [(f32, f32); 2],\n    /// a note waiting for this voice\'s fade-out to finish (the voice was stolen)\n    pending: Option<Note>,\n    /// the pending note\'s gate fell before it began\n    cancel: bool,\n    fade: u32,\n}\n\nimpl Voice {\n    pub fn active(&self) -> bool {\n        self.active\n    }\n\n    pub fn age(&self) -> u64 {\n        self.age\n    }\n\n    pub fn id(&self) -> Option<u32> {\n        self.id\n    }\n\n    /// the pitch the note started with (Hz)\n    pub fn base(&self) -> f32 {\n        self.base\n    }\n\n    pub fn sustained(&self) -> bool {\n        self.sustained\n    }\n\n    pub fn start(&mut self, n: Note, p: &Patch, rate: f64) {\n        *self = Voice::default();\n        self.active = true;\n        self.age = n.age;\n        self.id = Some(n.id);\n        self.hz = n.hz.clamp(8.0, 12_000.0);\n        self.base = self.hz;\n        self.vel = n.vel.clamp(0.0, 1.0);\n        if n.from > 0.0 && p.glide > 0.0 {\n            self.slide(n.from, p.glide, rate);\n        }\n        self.noise = White::new(mix(n.seed));\n        self.lfo[0].start(mix(n.seed ^ 1));\n        self.lfo[1].start(mix(n.seed ^ 2));\n        for k in 0..2 {\n            self.fenv[k].gate_on(&fe_times(p, k), rate);\n            self.aenv[k].gate_on(&ae_times(p, k), rate);\n        }\n    }\n\n    /// taken over by a newer note: fades out for `FADE` samples, then the note starts in its place\n    pub fn steal(&mut self, n: Note) {\n        self.pending = Some(n);\n        self.cancel = false;\n        self.fade = FADE;\n        self.age = n.age;\n        self.id = Some(n.id);\n        self.base = n.hz.clamp(8.0, 12_000.0);\n        self.sustained = false;\n    }\n\n    /// a legato pitch change (a note on for a sounding id, a bend): at once\n    pub fn set_pitch(&mut self, hz: f32) {\n        let hz = hz.clamp(8.0, 12_000.0);\n        match &mut self.pending {\n            Some(n) => n.hz = hz,\n            None => {\n                self.hz = hz;\n                self.glide_left = 0;\n            }\n        }\n    }\n\n    /// amp envelope 1\'s level\n    pub fn env(&self) -> f32 {\n        self.aenv[0].level()\n    }\n\n    /// From `from` to the pitch it holds (`self.hz`) in `secs`, even steps in octaves, one per control step.\n    fn slide(&mut self, from: f32, secs: f32, rate: f64) {\n        let from = from.clamp(8.0, 12_000.0);\n        let steps = (f64::from(secs) * rate / f64::from(CTRL)).round() as u32;\n        self.target = self.hz;\n        if steps == 0 || from == self.hz {\n            self.glide_left = 0;\n            return;\n        }\n        self.glide_oct = log2(f64::from(from));\n        self.glide_step = (log2(f64::from(self.hz)) - self.glide_oct) / f64::from(steps);\n        self.glide_left = steps;\n        self.hz = from;\n    }\n\n    /// mono: the next note on the sounding voice – the envelopes start again from where they are, the pitch glides\n    pub fn retrigger(&mut self, n: Note, p: &Patch, rate: f64) {\n        if self.pending.is_some() {\n            self.steal(n);\n            return;\n        }\n        if !self.active {\n            self.start(n, p, rate);\n            return;\n        }\n        let from = self.hz;\n        self.age = n.age;\n        self.id = Some(n.id);\n        self.vel = n.vel.clamp(0.0, 1.0);\n        self.glide(from, n.hz, p, rate);\n        for k in 0..2 {\n            self.fenv[k].gate_on(&fe_times(p, k), rate);\n            self.aenv[k].gate_on(&ae_times(p, k), rate);\n        }\n    }\n\n    /// legato: another held note takes the sounding voice – only the pitch moves (glides), the envelopes go on\n    pub fn legato(&mut self, id: u32, hz: f32, p: &Patch, rate: f64) {\n        if let Some(n) = &mut self.pending {\n            n.id = id;\n            n.hz = hz.clamp(8.0, 12_000.0);\n            self.id = Some(id);\n            self.base = n.hz;\n            return;\n        }\n        let from = self.hz;\n        self.id = Some(id);\n        self.glide(from, hz, p, rate);\n    }\n\n    fn glide(&mut self, from: f32, to: f32, p: &Patch, rate: f64) {\n        self.hz = to.clamp(8.0, 12_000.0);\n        self.base = self.hz;\n        self.sustained = false;\n        self.glide_left = 0;\n        if p.glide > 0.0 {\n            self.slide(from, p.glide, rate);\n        }\n        // the new pitch is read at once, not at the next control step\n        self.ctr = 0;\n    }\n\n    /// the note off (or the pedal came up): release both envelopes\n    pub fn release(&mut self, p: &Patch, rate: f64) {\n        self.id = None;\n        self.sustained = false;\n        if self.pending.is_some() {\n            self.cancel = true;\n            return;\n        }\n        for k in 0..2 {\n            self.fenv[k].gate_off(&fe_times(p, k), rate);\n            self.aenv[k].gate_off(&ae_times(p, k), rate);\n        }\n    }\n\n    /// the note off came but the pedal holds the note\n    pub fn hold(&mut self) {\n        self.id = None;\n        self.sustained = true;\n    }\n\n    /// control rate: everything that needs `exp2`, `log2` or `tan`\n    fn update(&mut self, p: &Patch, rate: f64) {\n        let lfo = [f64::from(self.lfo_v[0]), f64::from(self.lfo_v[1])];\n        let fe = [f64::from(self.fe_v[0]), f64::from(self.fe_v[1])];\n        let vel = f64::from(self.vel);\n        let oct = log2(f64::from(self.hz)) - log2(C4); // octaves above middle C\n        let common = lfo[0] * f64::from(p.l1_pitch) + lfo[1] * f64::from(p.l2_pitch) + vel * f64::from(p.vel_pitch);\n        let pwm = lfo[0] * f64::from(p.l1_pwm) + lfo[1] * f64::from(p.l2_pwm) + vel * f64::from(p.vel_pwm);\n        let oscs = [(p.o1_semi, p.o1_fine, p.o1_key, p.o1_pw), (p.o2_semi, p.o2_fine, p.o2_key, p.o2_pw)];\n        // oscillator 2 alone: its own envelope and LFO sends (they move it against a synced oscillator 1)\n        let only2 = [0.0, fe[1] * f64::from(p.fe2_p2) + lfo[0] * f64::from(p.l1_p2) + lfo[1] * f64::from(p.l2_p2)];\n        for (n, &(semi, fine, key, width)) in oscs.iter().enumerate() {\n            let st = f64::from(semi) + f64::from(fine) / 100.0 + common + only2[n] + 12.0 * oct * f64::from(key);\n            self.inc[n] = C4 * exp2(st / 12.0) / rate;\n            self.pw[n] = (f64::from(width) + pwm).clamp(0.02, 0.98);\n        }\n        let filters = [\n            (p.f1_cutoff, p.f1_res, p.f1_key, p.f1_env, p.f1_vel, p.f1_velres, p.l1_f1, p.l2_f1),\n            (p.f2_cutoff, p.f2_res, p.f2_key, p.f2_env, p.f2_vel, p.f2_velres, p.l1_f2, p.l2_f2),\n        ];\n        for (n, &(cut, res, key, env, fvel, velres, l1, l2)) in filters.iter().enumerate() {\n            let octaves =\n                f64::from(key) * oct + 6.0 * f64::from(env) * fe[n] + 4.0 * f64::from(fvel) * vel + f64::from(l1) * lfo[0] + f64::from(l2) * lfo[1];\n            let res = (f64::from(res) + f64::from(velres) * vel).clamp(0.0, 1.0) as f32;\n            self.coef[n] = Coef::new(f64::from(cut) * exp2(octaves), res, rate);\n        }\n        let amps = [(p.a1_level, p.a1_pan, p.a1_vel, p.a1_key, p.l1_a1, p.l2_a1), (p.a2_level, p.a2_pan, p.a2_vel, p.a2_key, p.l1_a2, p.l2_a2)];\n        for (n, &(level, pn, avel, key, t1, t2)) in amps.iter().enumerate() {\n            let by_vel = (1.0 - f64::from(avel)) + f64::from(avel) * vel;\n            let by_key = exp2(f64::from(key) * oct * 0.5).clamp(0.1, 4.0);\n            let trem = (1.0 + 0.5 * (f64::from(t1) * (lfo[0] - 1.0) + f64::from(t2) * (lfo[1] - 1.0))).max(0.0);\n            self.amp[n] = (f64::from(level) * by_vel * by_key * trem) as f32;\n            self.pan[n] = pan::gains(pn);\n        }\n        if self.glide_left > 0 {\n            self.glide_left -= 1;\n            self.glide_oct += self.glide_step;\n            self.hz = if self.glide_left == 0 { self.target } else { exp2(self.glide_oct) as f32 };\n        }\n    }\n\n    /// One sample at the absolute `beat`: (left, right). The voice frees itself when both amp envelopes are done.\n    pub fn render(&mut self, p: &Patch, rate: f64, beat: f64) -> (f32, f32) {\n        let mut gain = 1.0;\n        if let Some(n) = self.pending {\n            self.fade -= 1;\n            if self.fade == 0 {\n                let cancel = self.cancel;\n                self.start(n, p, rate);\n                if cancel {\n                    self.release(p, rate);\n                }\n            } else {\n                gain = self.fade as f32 / FADE as f32;\n            }\n        }\n        if self.ctr % CTRL == 0 {\n            self.update(p, rate);\n        }\n        self.ctr = self.ctr.wrapping_add(1);\n\n        for k in 0..2 {\n            self.lfo_v[k] = self.lfo[k].tick(&lfo_settings(p, k), rate, beat);\n            self.fe_v[k] = self.fenv[k].tick(&fe_times(p, k), rate);\n        }\n        let ae = [self.aenv[0].tick(&ae_times(p, 0), rate), self.aenv[1].tick(&ae_times(p, 1), rate)];\n\n        let t1 = self.osc[0].tick(Wave::from_param(p.o1_wave), self.inc[0], self.pw[0], None);\n        let master = if p.o2_sync >= 0.5 { t1.wrap } else { None };\n        let t2 = self.osc[1].tick(Wave::from_param(p.o2_wave), self.inc[1], self.pw[1], master);\n        let s1 = self.sub[0].tick(t1.wrap);\n        let s2 = self.sub[1].tick(t2.wrap);\n        let sources = [\n            (t1.value * p.o1_level, p.o1_route),\n            (s1 * p.o1_sub, p.sub1_route),\n            (t2.value * p.o2_level, p.o2_route),\n            (s2 * p.o2_sub, p.sub2_route),\n            (self.noise.next() * p.noise_level, p.noise_route),\n        ];\n        let (mut in1, mut in2) = (0.0f32, 0.0f32);\n        for (v, route) in sources {\n            let route = route.round() as i32; // 0 filter 1, 1 filter 2, 2 both\n            if route != 1 {\n                in1 += v;\n            }\n            if route >= 1 {\n                in2 += v;\n            }\n        }\n        let y1 = self.svf[0].tick(&self.coef[0], Mode::from_param(p.f1_mode), svf::drive(in1, p.f1_drive));\n        if p.f_serial >= 0.5 {\n            in2 += p.f1_to_f2 * y1;\n        }\n        let y2 = self.svf[1].tick(&self.coef[1], Mode::from_param(p.f2_mode), svf::drive(in2, p.f2_drive));\n\n        let (a1, a2) = (y1 * ae[0] * self.amp[0] * gain, y2 * ae[1] * self.amp[1] * gain);\n        let (l, r) = (a1 * self.pan[0].0 + a2 * self.pan[1].0, a1 * self.pan[0].1 + a2 * self.pan[1].1);\n        if self.aenv[0].idle() && self.aenv[1].idle() && self.pending.is_none() {\n            self.active = false;\n        }\n        (l, r)\n    }\n}\n')
 WHERE `id` = 'analog' AND JSON_CONTAINS(`data`, 'true', '$.factory')
   AND JSON_CONTAINS_PATH(`data`, 'one', '$.files."svf.rs"') = 0
   AND INSTR(JSON_UNQUOTE(JSON_EXTRACT(`data`, '$.files."params.rs"')), 'name = "level"') = 0;

UPDATE `entity_versions` e
  JOIN `catalog_modules` m ON m.`id` = 'analog' AND JSON_CONTAINS(m.`data`, 'true', '$.factory')
   SET e.`json` = m.`data`
 WHERE e.`entity_key` = 'module:analog' AND e.`status` = 'published'
   AND e.`message` = 'factory module (migration 2026-11-05-factory-modules)'
   AND INSTR(JSON_UNQUOTE(JSON_EXTRACT(m.`data`, '$.files."params.rs"')), 'name = "level"') > 0
   AND INSTR(JSON_UNQUOTE(JSON_EXTRACT(e.`json`, '$.files."params.rs"')), 'name = "level"') = 0;
